"""Shared helpers for compress.py / decompress.py.

Container format (version 1)
----------------------------
Every original file's bytes are concatenated, in manifest order, into one
logical stream.  That stream is cut into shards; each shard is an independently
compressed frame whose *compressed* size stays below the per-file limit.  A
manifest (compressed, and split into parts if huge) records the directory tree,
the ordered file list with sizes, and the shard list.

Layout produced inside the output directory::

    index.json        tiny plain JSON: codec, container names, counts
    <meta_dir>/...    compressed manifest parts, in a fanout-bounded tree
    <data_dir>/...    shards, in a fanout-bounded tree

Container names are picked so they cannot collide with any top-level name of
the original dataset, which makes in-place restoration safe.
"""

import inspect
import json
import os

FORMAT_MAGIC = "reshard"
FORMAT_VERSION = 1

MAX_ENTRIES_PER_DIR = 30
MAX_FILE_BYTES = 15 * 1000 * 1000        # task limit (also < 15 MiB)
SHARD_TARGET_BYTES = 11 * 1000 * 1000    # cut here: leaves ample headroom
READ_BLOCK = 1 << 20

INDEX_NAME = "index.json"
SHARD_EXT = ".bin"
META_EXT = ".bin"


# ---------------------------------------------------------------- codec ----
def _zstd():
    try:
        import zstandard
    except Exception:
        return None
    return zstandard


def pick_codec():
    return "zstd" if _zstd() is not None else "zlib"


def _kwargs_for(callable_obj, wanted):
    """Keep only kwargs the installed version actually accepts."""
    try:
        params = inspect.signature(callable_obj).parameters
    except (TypeError, ValueError):
        return {}
    if any(p.kind == p.VAR_KEYWORD for p in params.values()):
        return dict(wanted)
    return {k: v for k, v in wanted.items() if k in params}


def new_compressor(codec):
    """Return an object with .compress(bytes) and .flush() -> bytes."""
    if codec == "zstd":
        zstd = _zstd()
        if zstd is None:
            raise RuntimeError("shards use zstd but the zstandard package is missing")
        kwargs = _kwargs_for(zstd.ZstdCompressor, {"level": 6, "threads": -1})
        for attempt in (kwargs, {k: v for k, v in kwargs.items() if k == "level"}, {}):
            try:
                return zstd.ZstdCompressor(**attempt).compressobj()
            except (TypeError, ValueError, AttributeError):
                continue
        raise RuntimeError("could not build a zstd compressor")
    if codec == "zlib":
        import zlib

        return zlib.compressobj(6)
    raise ValueError("unknown codec %r" % (codec,))


def new_decompressor(codec):
    """Return an object with .decompress(bytes) -> bytes."""
    if codec == "zstd":
        zstd = _zstd()
        if zstd is None:
            raise RuntimeError(
                "archive is zstd-compressed but the zstandard package is missing"
            )
        return zstd.ZstdDecompressor().decompressobj()
    if codec == "zlib":
        import zlib

        return zlib.decompressobj()
    raise ValueError("unknown codec %r" % (codec,))


# --------------------------------------------------------------- layout ----
def tree_depth(count, fanout=MAX_ENTRIES_PER_DIR):
    """Depth needed so `count` leaves fit with at most `fanout` per directory."""
    depth = 1
    capacity = fanout
    while capacity < max(count, 1):
        capacity *= fanout
        depth += 1
    return depth


def tree_path(index, depth, ext, fanout=MAX_ENTRIES_PER_DIR):
    digits = []
    value = index
    for _ in range(depth):
        digits.append(value % fanout)
        value //= fanout
    digits.reverse()
    parts = ["%02d" % d for d in digits[:-1]]
    parts.append("%02d%s" % (digits[-1], ext))
    return "/".join(parts)


def place_flat_files(staging_dir, staged_names, dest_root, ext):
    """Move sequentially staged files into a fanout-bounded tree under dest_root."""
    depth = tree_depth(len(staged_names))
    placed = []
    for i, name in enumerate(staged_names):
        rel = tree_path(i, depth, ext)
        dest = os.path.join(dest_root, *rel.split("/"))
        parent = os.path.dirname(dest)
        if parent:
            os.makedirs(parent, exist_ok=True)
        os.replace(os.path.join(staging_dir, name), dest)
        placed.append(rel)
    return placed


# ---------------------------------------------------------------- misc -----
def rel_join(rel_dir, name):
    return name if not rel_dir else rel_dir + "/" + name


def unique_name(base, taken):
    name = base
    i = 1
    while name in taken:
        name = "%s_%d" % (base, i)
        i += 1
    return name


def dump_json(obj):
    return json.dumps(obj, separators=(",", ":")).encode("utf-8")
