#!/usr/bin/env python3
"""Restore a directory produced by compress.py back to its original form,
in place.

Usage: python decompress.py <resharded_dir>
"""

import argparse
import bisect
import json
import multiprocessing
import os
import shutil
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from reshard_common import (  # noqa: E402
    FORMAT_MAGIC,
    INDEX_NAME,
    READ_BLOCK,
    new_decompressor,
)


# ---------------------------------------------------------------- index ----
def load_index(root):
    candidates = []
    direct = os.path.join(root, INDEX_NAME)
    if os.path.isfile(direct):
        candidates.append(direct)
    for name in sorted(os.listdir(root)):
        path = os.path.join(root, name)
        if path != direct and os.path.isfile(path) and name.endswith(".json"):
            candidates.append(path)
    for path in candidates:
        try:
            if os.path.getsize(path) > 4 << 20:
                continue
            with open(path, "rb") as fh:
                data = json.loads(fh.read().decode("utf-8"))
        except Exception:
            continue
        if isinstance(data, dict) and data.get("format") == FORMAT_MAGIC:
            return path, data
    raise SystemExit(
        "%s does not look like a resharded directory (no %s found)" % (root, INDEX_NAME)
    )


def load_manifest(root, index):
    codec = index["codec"]
    dec = new_decompressor(codec)
    out = []
    for rel in index["meta_parts"]:
        path = os.path.join(root, index["meta_dir"], *rel.split("/"))
        with open(path, "rb") as fh:
            while True:
                block = fh.read(READ_BLOCK)
                if not block:
                    break
                out.append(dec.decompress(block))
    manifest = json.loads(b"".join(out).decode("utf-8"))
    if manifest.get("format") != FORMAT_MAGIC:
        raise SystemExit("corrupt manifest in %s" % root)
    return manifest


# ------------------------------------------------------------- restore -----
def cumulative_offsets(files):
    offsets = []
    total = 0
    for entry in files:
        offsets.append(total)
        total += entry[1]
    return offsets, total


def create_skeleton(root, manifest):
    for rel in manifest["dirs"]:
        os.makedirs(os.path.join(root, *rel.split("/")), exist_ok=True)
    for rel, size, _mode in manifest["files"]:
        path = os.path.join(root, *rel.split("/"))
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "wb") as fh:
            if size:
                fh.truncate(size)


def finalize(root, manifest):
    for rel, size, mode in manifest["files"]:
        path = os.path.join(root, *rel.split("/"))
        actual = os.path.getsize(path)
        if actual != size:
            raise SystemExit(
                "restored %s has %d bytes, expected %d" % (rel, actual, size)
            )
        try:
            os.chmod(path, mode)
        except OSError:
            pass
    for rel, target in manifest.get("links", []):
        path = os.path.join(root, *rel.split("/"))
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        if os.path.islink(path) or os.path.exists(path):
            if os.path.islink(path) or os.path.isfile(path):
                os.remove(path)
            else:
                shutil.rmtree(path)
        os.symlink(target, path)


_WORKER = {}


def _init_worker(root, files, offsets, codec, data_dir):
    _WORKER.update(
        root=root, files=files, offsets=offsets, codec=codec, data_dir=data_dir
    )


def _restore_shard(task):
    shard_rel, start, usize = task
    root = _WORKER["root"]
    files = _WORKER["files"]
    offsets = _WORKER["offsets"]
    dec = new_decompressor(_WORKER["codec"])
    path = os.path.join(root, _WORKER["data_dir"], *shard_rel.split("/"))

    idx = max(bisect.bisect_right(offsets, start) - 1, 0)
    pos = start
    end = start + usize
    fh_out = None
    open_idx = -1
    try:
        with open(path, "rb") as fh:
            pending = b""
            while True:
                block = fh.read(READ_BLOCK)
                if not block:
                    break
                data = dec.decompress(block)
                if not data:
                    continue
                pending += data
                while pending:
                    while idx < len(files) and pos >= offsets[idx] + files[idx][1]:
                        idx += 1
                    if idx >= len(files):
                        raise RuntimeError("shard %s overruns file table" % shard_rel)
                    rel, size, _mode = files[idx]
                    local = pos - offsets[idx]
                    take = min(size - local, len(pending))
                    if open_idx != idx:
                        if fh_out is not None:
                            fh_out.close()
                        fh_out = open(
                            os.path.join(root, *rel.split("/")), "r+b"
                        )
                        open_idx = idx
                    fh_out.seek(local)
                    fh_out.write(pending[:take])
                    pending = pending[take:]
                    pos += take
    finally:
        if fh_out is not None:
            fh_out.close()
    if pos != end:
        raise RuntimeError(
            "shard %s produced %d bytes, expected %d" % (shard_rel, pos - start, usize)
        )
    return shard_rel


def restore_data(root, manifest, index, jobs):
    files = manifest["files"]
    offsets, total = cumulative_offsets(files)
    if manifest.get("total_bytes", total) != total:
        raise SystemExit("manifest size mismatch in %s" % root)
    tasks = []
    pos = 0
    for shard_rel, usize, _csize in manifest["shards"]:
        tasks.append((shard_rel, pos, usize))
        pos += usize
    if pos != total:
        raise SystemExit("shards cover %d of %d bytes" % (pos, total))
    if not tasks:
        return
    jobs = max(1, min(jobs, len(tasks)))
    if jobs == 1:
        _init_worker(root, files, offsets, manifest["codec"], index["data_dir"])
        for task in tasks:
            _restore_shard(task)
        return
    pool = multiprocessing.Pool(
        processes=jobs,
        initializer=_init_worker,
        initargs=(root, files, offsets, manifest["codec"], index["data_dir"]),
    )
    try:
        for _ in pool.imap_unordered(_restore_shard, tasks):
            pass
    finally:
        pool.close()
        pool.join()


def cleanup(root, index_path, index):
    for key in ("data_dir", "meta_dir"):
        name = index.get(key)
        if not name:
            continue
        path = os.path.join(root, name)
        if os.path.isdir(path):
            shutil.rmtree(path)
    if os.path.isfile(index_path):
        os.remove(index_path)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Restore a resharded directory in place."
    )
    parser.add_argument("resharded_dir")
    parser.add_argument(
        "-j",
        "--jobs",
        type=int,
        default=0,
        help="worker processes (default: all available cores)",
    )
    args = parser.parse_args(argv)

    root = os.path.abspath(args.resharded_dir)
    if not os.path.isdir(root):
        parser.error("directory does not exist: %s" % args.resharded_dir)
    jobs = args.jobs if args.jobs and args.jobs > 0 else (os.cpu_count() or 1)

    index_path, index = load_index(root)
    manifest = load_manifest(root, index)
    create_skeleton(root, manifest)
    restore_data(root, manifest, index, jobs)
    finalize(root, manifest)
    cleanup(root, index_path, index)
    print(
        "restored %d files (%d bytes) in %s"
        % (len(manifest["files"]), manifest.get("total_bytes", 0), root)
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
